/**
 * Studio Preview Rendering — Phase 6.3
 *
 * Generates and caches preset-applied preview images for discover stories,
 * hero cards, and non-signature preset thumbnails.
 *
 * Collection covers for SIGNATURE_COLLECTIONS load from real CC0-verified
 * photographic assets in /assets/collections/.
 *
 * Signature Look previews for the 5 Signature Looks load from preset-rendered
 * WebP photographic assets in /assets/signature-looks/ generated by Auvori's
 * production WebGL2 PhotoPipeline.
 */

import { PRESETS } from '../data/presets';
import { PhotoPipeline } from '../engine/pipeline/photo-pipeline';
import {
  getSamplePhotoUrl,
  SamplePhotoId,
  COLLECTION_COVERS,
  SIGNATURE_LOOK_PREVIEWS
} from './samplePhoto';

const renderedPreviewCache = new Map<string, string>();
const loadedSampleImgs = new Map<SamplePhotoId, Promise<HTMLImageElement>>();
let studioPreviewPipeline: PhotoPipeline | null = null;
let renderQueue: Promise<void> = Promise.resolve();

function getStudioPreviewPipeline(): PhotoPipeline {
  if (!studioPreviewPipeline) {
    studioPreviewPipeline = new PhotoPipeline({
      preferWebGL2: true,
      preferWorkerFallback: true
    });
  }
  return studioPreviewPipeline;
}

function loadSampleImage(sampleId: SamplePhotoId): Promise<HTMLImageElement> {
  const existing = loadedSampleImgs.get(sampleId);
  if (existing) return existing;

  const p = new Promise<HTMLImageElement>((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = getSamplePhotoUrl(sampleId);
  });
  loadedSampleImgs.set(sampleId, p);
  return p;
}

/**
 * Returns the collection cover URL for a given collection ID.
 *
 * Phase 6.3: Returns the pre-generated real photographic WebP asset from
 * /assets/collections/. No canvas rendering is performed.
 * Falls back to undefined if the collection has no production cover.
 */
export function getCollectionCoverUrl(collectionId: string): string | undefined {
  return COLLECTION_COVERS[collectionId];
}

/**
 * Returns the preset-rendered photographic preview URL for a Signature Look.
 * Loads directly from /assets/signature-looks/ with no synthetic illustration fallback.
 */
export function getSignatureLookPreviewUrl(presetId: string): string | undefined {
  return SIGNATURE_LOOK_PREVIEWS[presetId]?.previewPath;
}

/**
 * Returns the unedited photographic source URL paired with a Signature Look.
 */
export function getSignatureLookSourceUrl(presetId: string): string | undefined {
  return SIGNATURE_LOOK_PREVIEWS[presetId]?.sourcePath;
}

/**
 * Returns the intentional CSS object-position focal point for a Signature Look card.
 */
export function getSignatureLookObjectPosition(presetId: string): string {
  return SIGNATURE_LOOK_PREVIEWS[presetId]?.objectPosition ?? '50% 50%';
}

/**
 * Generates and caches a crisp 260px editorial preview of a preset applied to a
 * studio sample photo using GPU/Worker PhotoPipeline.
 *
 * Not used for: SIGNATURE_COLLECTIONS covers (use getCollectionCoverUrl()) or
 * Signature Looks cards (use getSignatureLookPreviewUrl()).
 */
export async function renderStudioPresetPreview(
  presetId: string,
  sampleId: SamplePhotoId = 'cafe'
): Promise<string> {
  const key = `${sampleId}:${presetId}`;
  const hit = renderedPreviewCache.get(key);
  if (hit) return hit;

  const preset = PRESETS.find((p) => p.id === presetId);
  if (!preset) return '';

  const job = renderQueue.then(async () => {
    const cachedAgain = renderedPreviewCache.get(key);
    if (cachedAgain) return cachedAgain;

    const img = await loadSampleImage(sampleId);
    const canvas = document.createElement('canvas');
    await getStudioPreviewPipeline().renderPreview({
      source: img,
      sourceId: `sample_${sampleId}`,
      sourceRevision: 1,
      transformRevision: 1,
      recipe: preset.recipe,
      targetCanvas: canvas,
      maxDimension: 260
    });
    const url = canvas.toDataURL('image/jpeg', 0.82);
    renderedPreviewCache.set(key, url);
    return url;
  });

  renderQueue = job.then(
    () => undefined,
    () => undefined
  );

  return job;
}
